import{_ as s,o as t,c as e,a3 as i}from"./chunks/framework.Dz5Q8p4s.js";const m=JSON.parse('{"title":"Acceleration & Distillation in Video Generation","description":"","frontmatter":{"title":"Acceleration & Distillation in Video Generation","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/acceleration-distillation.md","filePath":"en/tutorials/acceleration-distillation.md","lastUpdated":null}'),n={name:"en/tutorials/acceleration-distillation.md"};function l(r,a,o,p,c,h){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="acceleration-distillation-in-video-generation" tabindex="-1">Acceleration &amp; Distillation in Video Generation <a class="header-anchor" href="#acceleration-distillation-in-video-generation" aria-label="Permalink to &quot;Acceleration &amp; Distillation in Video Generation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/acceleration-distillation">视频生成的加速与蒸馏</a><strong>Coverage</strong>: June 2025 – July 2026, with earlier foundational work included as background. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-acceleration-distillation">59 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues, so you can navigate the Chinese text, cite it, or decide whether it is worth reading. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/acceleration-distillation">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>Video diffusion is slow for three separable reasons, and almost every acceleration paper attacks exactly one of them: the number of denoising steps <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>, the cost of a single forward pass <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">model</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>, and the number of spatio-temporal tokens <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">token</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>. The tutorial builds that decomposition first, then uses it as the coordinate system for everything else — so that a reader can look at any new method and immediately say which term it reduces and what it trades away.</p><p>Its central technical claim is that step distillation splits cleanly into <strong>trajectory distillation</strong> (make the student follow the teacher&#39;s ODE path) and <strong>distribution distillation</strong> (make the student&#39;s output distribution match the teacher&#39;s), that adversarial objectives are a third axis rather than a competitor, and that the defining trend of 2026 is hybridisation of all three.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><p>Scope, intended reader, prerequisites, and the argument&#39;s overall shape.</p><ul><li>0.1 What problem this tutorial solves</li><li>0.2 Intended readers and assumed background</li><li>0.3 The logic of the whole text</li></ul><h3 id="chapter-1-—-motivation-why-video-generation-is-so-slow" tabindex="-1">Chapter 1 — Motivation: why video generation is so slow <a class="header-anchor" href="#chapter-1-—-motivation-why-video-generation-is-so-slow" aria-label="Permalink to &quot;Chapter 1 — Motivation: why video generation is so slow&quot;">​</a></h3><p>Decomposes latency into three multiplicative sources and pairs each with its family of remedies.</p><ul><li>1.1 First source: the number of denoising steps <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span></li><li>1.2 Second source: the cost of one forward pass <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">model</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></li><li>1.3 Third source: the spatio-temporal token count <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">token</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></li><li>1.4 A &quot;source of slowness → antidote&quot; cross-reference table</li></ul><h3 id="chapter-2-—-foundations-diffusion-flow-matching-and-video-diffusion-models" tabindex="-1">Chapter 2 — Foundations: diffusion, flow matching, and video diffusion models <a class="header-anchor" href="#chapter-2-—-foundations-diffusion-flow-matching-and-video-diffusion-models" aria-label="Permalink to &quot;Chapter 2 — Foundations: diffusion, flow matching, and video diffusion models&quot;">​</a></h3><p>The minimum theory needed to see <em>why</em> step count is compressible at all.</p><ul><li>2.1 Diffusion models: adding and removing noise</li><li>2.2 From SDE to PF-ODE: why the number of steps can be compressed</li><li>2.3 Flow matching and rectified flow</li><li>2.4 Video diffusion architectures: 3D VAE + DiT + 3D attention</li><li>2.5 Two generation paradigms: bidirectional vs autoregressive</li></ul><h3 id="chapter-3-—-the-mathematics-of-distillation-trajectory-vs-distribution" tabindex="-1">Chapter 3 — The mathematics of distillation: trajectory vs distribution <a class="header-anchor" href="#chapter-3-—-the-mathematics-of-distillation-trajectory-vs-distribution" aria-label="Permalink to &quot;Chapter 3 — The mathematics of distillation: trajectory vs distribution&quot;">​</a></h3><p>The conceptual core. Distillation is framed as reproducing a many-step teacher in few student steps, and the two ways of defining &quot;reproduce&quot; turn out to have very different failure modes.</p><ul><li>3.1 Distillation = reproducing the teacher&#39;s many-step result in few student steps</li><li>3.2 Trajectory distillation</li><li>3.3 Distribution distillation</li><li>3.4 Adversarial distillation</li><li>3.5 The key trade-off: why hybrid objectives became the 2026 mainstream</li></ul><h3 id="chapter-4-—-task-map-where-acceleration-actually-happens" tabindex="-1">Chapter 4 — Task map: where acceleration actually happens <a class="header-anchor" href="#chapter-4-—-task-map-where-acceleration-actually-happens" aria-label="Permalink to &quot;Chapter 4 — Task map: where acceleration actually happens&quot;">​</a></h3><ul><li>4.1 Split by input–output modality</li><li>4.2 Split by duration and interactivity (the most important axis)</li><li>4.3 An observation: acceleration has become task-specific</li></ul><h3 id="chapter-5-—-benchmarks-and-metrics-measuring-fast-and-good" tabindex="-1">Chapter 5 — Benchmarks and metrics: measuring &quot;fast <em>and</em> good&quot; <a class="header-anchor" href="#chapter-5-—-benchmarks-and-metrics-measuring-fast-and-good" aria-label="Permalink to &quot;Chapter 5 — Benchmarks and metrics: measuring &quot;fast *and* good&quot;&quot;">​</a></h3><ul><li>5.1 Quality metrics</li><li>5.2 Efficiency metrics — the real protagonist of an acceleration paper</li><li>5.3 Two traps in evaluation</li><li>5.4 Newer benchmarks built for acceleration</li></ul><h3 id="chapter-6-—-data-what-distillation-is-actually-trained-on" tabindex="-1">Chapter 6 — Data: what distillation is actually trained on <a class="header-anchor" href="#chapter-6-—-data-what-distillation-is-actually-trained-on" aria-label="Permalink to &quot;Chapter 6 — Data: what distillation is actually trained on&quot;">​</a></h3><ul><li>6.1 Three routes for distillation data</li><li>6.2 Key concepts in distillation data</li><li>6.3 Datasets and material for acceleration / distillation</li><li>6.4 One practical lesson</li></ul><h3 id="chapter-7-—-the-method-compendium-core-chapter" tabindex="-1">Chapter 7 — The method compendium (core chapter) <a class="header-anchor" href="#chapter-7-—-the-method-compendium-core-chapter" aria-label="Permalink to &quot;Chapter 7 — The method compendium (core chapter)&quot;">​</a></h3><p>The largest chapter: ten method families, each with motivation → core idea → mechanism or formula → representative work → strengths and weaknesses.</p><ul><li>7.1 Step distillation: from 50 steps down to 1–4</li><li>7.2 Autoregressive / streaming / causal distillation</li><li>7.3 Training-free caching</li><li>7.4 Sparse attention</li><li>7.5 Quantisation</li><li>7.6 Pruning and dynamic computation</li><li>7.7 Parallelism and system-level optimisation</li><li>7.8 Progressive resolution and spectral methods</li><li>7.9 Speculative decoding</li><li>7.10 On-device and mobile deployment</li></ul><h3 id="chapter-8-—-composition-and-practical-recipes" tabindex="-1">Chapter 8 — Composition and practical recipes <a class="header-anchor" href="#chapter-8-—-composition-and-practical-recipes" aria-label="Permalink to &quot;Chapter 8 — Composition and practical recipes&quot;">​</a></h3><ul><li>8.1 An orthogonality matrix: which techniques stack</li><li>8.2 Representative recipes by scenario</li><li>8.3 Ordering and pitfalls when composing techniques</li></ul><h3 id="chapter-9-—-deployment-representative-accelerated-systems-per-task" tabindex="-1">Chapter 9 — Deployment: representative accelerated systems per task <a class="header-anchor" href="#chapter-9-—-deployment-representative-accelerated-systems-per-task" aria-label="Permalink to &quot;Chapter 9 — Deployment: representative accelerated systems per task&quot;">​</a></h3><h3 id="chapter-10-—-challenges-and-future-directions" tabindex="-1">Chapter 10 — Challenges and future directions <a class="header-anchor" href="#chapter-10-—-challenges-and-future-directions" aria-label="Permalink to &quot;Chapter 10 — Challenges and future directions&quot;">​</a></h3><ul><li>10.1 Unsolved challenges</li><li>10.2 Directions worth betting on</li><li>10.3 The whole tutorial in one sentence</li></ul><h3 id="appendices" tabindex="-1">Appendices <a class="header-anchor" href="#appendices" aria-label="Permalink to &quot;Appendices&quot;">​</a></h3><ul><li>Appendix A — Paper list by topic (surveys; step distillation; autoregressive/streaming/causal distillation; real-time autoregressive world models; caching; KV-cache management; sparse attention; quantisation/systems/parallelism; pruning, dynamic computation, progressive resolution, speculation; efficiency-related alignment, RL and datasets)</li><li>Appendix B — Glossary</li><li>Appendix C — Suggested learning path</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/autoregressive">Autoregressive Video Generation</a> — where few-step distillation meets streaming inference</li><li><a href="/notes/en/tutorials/post-training-rl">Post-Training &amp; Reinforcement Learning</a> — combining distillation with reward alignment</li><li><a href="/notes/en/tutorials/world-models">World Models</a> — why real-time interaction makes acceleration a hard requirement rather than a nicety</li></ul>',37)])])}const u=s(n,[["render",l]]);export{m as __pageData,u as default};
